def can_make_abc(cards):
    # Check if the row is already abc
    if 'abc' in cards:
        return 'YES'

    # Check if we can swap two cards
    for i in range(len(cards)):
        for j in range(i+1, len(cards)):
            if cards[i] == cards[j]:
                return 'NO'

    return 'YES'

def main():
    for i in range(1, 7):
        print(can_make_abc(input().split()))

if __name__ == "__main__":
    main()

def maxProduct(n, a):
    max_product = 0
    for i in range(n):
        for j in range(i+1, n):
            if a[i] == a[j]:
                max_product = max(max_product, a[i]*a[j])
    return max_product

def remove_black_cells(n, k):
    operations = []
    for i in range(n):
        if i % k == 0:
            operations.append('WW')
        else:
            operations.append('B')
    return min(operations)
