print(remove_black_cells(6, 3))  # Output: 1
print(remove_black_cells(7, 3))  # Output: 1
print(remove_black_cells(5, 4))  # Output: 4
print(remove_black_cells(5, 5))  # Output: 4
print(remove_black_cells(8, 2))  # Output: 1
print(remove_black_cells(10, 2))  # Output: 1
print(remove_black_cells(8, 1))  # Output: 0

def minOperations(a, k):
    n = len(a)
    product = 1
    for i in range(n):
        product *= a[i]

    for i in range(n):
        product %= k
        if product == 0:
            return i
    return -1

