def count_over_60(details):
    passengers = []
    for i in range(len(details)):
        phone_number = details[i][:10]
        gender = details[i][10]
        age = details[i][11:13]
        seat = details[i][14:16]
        passengers.append((phone_number, gender, age, seat))

    count = 0
    for phone_number, gender, age, seat in passengers:
        if age > 60:
            count += 1

    return count

def max_score(nums):
    score = 0
    for i in range(len(nums)):
        for j in range(len(nums[i])):
            if nums[i][j] > 0:
                score += nums[i][j]
    return score

def minExtraChars(s, dictionary):
    # Initialize a dictionary to store the number of extra characters
    extra_chars = {}

    # Initialize a counter to keep track of the number of extra characters
    extra_chars_count = 0

    # Iterate over each character in s
    for i in range(len(s)):
        # If the character is not in dictionary, add it to the extra_chars dictionary
        if s[i] not in dictionary:
            extra_chars[s[i]] = extra_chars.get(s[i], 0) + 1
        # If the character is in dictionary, increment the extra_chars_count
        else:
            extra_chars_count += extra_chars.get(s[i], 0)

    # Return the minimum number of extra characters
    return min(extra_chars.values())

def digit_sum(x):
    return sum(int(digit) for digit in str(x))

def count_good_numbers(num1, num2, min_sum, max_sum):
    good_numbers = 0
    for x in range(min_sum, max_sum + 1):
        digit_sum_x = digit_sum(x)
        if digit_sum_x >= min_sum and digit_sum_x <= max_sum:
            if digit_sum_x in range(min_sum, max_sum + 1):
                good_numbers += 1
    return good_numbers % (10**9 + 7)

def adjacent_elements(nums, queries):
    n = len(nums)
    answer = [0] * n

    for i in range(n):
        for j in range(i+1, n):
            if nums[j] == nums[j-1] and nums[j] != 0:
                answer[i] += 1
                answer[j] += 1

    return answer

def power_of_groups(nums):
    power_sum = 0
    for i in range(len(nums)):
        power_sum += (nums[i] ** 2) * min(nums[i], nums[i+1])
    return power_sum % (10**9 + 7)

def longestSemiRepetitiveSubstring(s):
    # Initialize a dictionary to store the length of each semi-repetitive substring
    lengths = {}

    # Initialize a counter to keep track of the length of each semi-repetitive substring
    counter = 0

    # Iterate through the string s
    for i in range(len(s)):
        # If the current character is a digit, increment the counter
        if s[i] in '0123456789':
            counter += 1

        # If the current character is not a digit, check if it is a semi-repetitive substring
        elif s[i] not in '0123456789':
            # If the current character is not a semi-repetitive substring, add it to the dictionary
            if s[i] not in lengths:
                lengths[s[i]] = counter
                counter = 1
            else:
                # If the current character is a semi-repetitive substring, increase the length of the current substring
                lengths[s[i]] += 1

    # Return the length of the longest semi-repetitive substring
    return max(lengths.values())

def losers(n, k):
    answer = []
    for i in range(n):
        if i * k > n:
            answer.append(i)
    return answer

def isValidBinaryArray(derived):
    n = len(derived)
    for i in range(n):
        if i == n - 1:
            derived[i] = derived[i] ^ derived[0]
        else:
            derived[i] = derived[i] ^ derived[i + 1]
    return derived

def remove_substring(s, substrings):
    if not substrings:
        return s

    for substring in substrings:
        if substring in s:
            s = s.replace(substring, '')

    return s

def minCost(nums, x):
    n = len(nums)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = nums[0]
    for i in range(1, n + 1):
        for j in range(i):
            dp[i][j] = max(dp[i - 1][j], dp[i][j - nums[i - 1]] + x)
    return dp[n][n]

def is_palindrome(s):
    return s == s[::-1]

def make_palindrome(s):
    return s if is_palindrome(s) else s[::-1]

def invert_string(s):
    n = len(s)
    i = 0
    while i < n:
        if s[i] == '0':
            s[i] = '1'
            i += 1
        elif s[i] == '1':
            s[i] = '0'
            i += 1
    return i

def remove_trailing_zeros(num):
    if len(num) == 0:
        return "0"
    else:
        return int(num)

def canTraverse(nums):
    # Initialize a set to keep track of the indices we've already visited
    visited = set()

    # Initialize a list to keep track of the indices we've already visited
    indices = []

    # Traverse through the array
    for i in range(len(nums)):
        # If the current index is not in the set of visited indices, add it
        if i not in visited:
            indices.append(i)

            # If the current index is not in the set of visited indices, add it
            if i not in visited:
                visited.add(i)

    # If we've visited all the indices, return true
    return all(i in indices for i in range(len(nums)))

def lexicographically_smallest_substring(s):
    # Initialize a dictionary to store the frequency of each character
    frequency = {}

    # Initialize a counter to count the frequency of each character
    count = 0

    # Iterate over the string
    for i in range(len(s)):
        # If the character is not in the dictionary, add it to the dictionary
        if s[i] not in frequency:
            frequency[s[i]] = 1
            count += 1
        # If the character is in the dictionary, increment the frequency
        else:
            frequency[s[i]] += 1
            count += 1

    # Find the lexicographically smallest string
    min_string = ""
    for i in range(len(s)):
        # If the frequency of the character is less than the current string, append the character to the string
        if frequency[s[i]] < min_string:
            min_string = s[i]

    return min_string

def generate_beautiful_pairs(nums):
    beautiful_pairs = 0
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if nums[i] % 10 == 0 and nums[j] % 10 == 0:
                beautiful_pairs += 1
    return beautiful_pairs

def find_servers_without_requests(n, logs, x, queries):
    arr = [0]*len(queries)
    for i in range(len(queries)):
        arr[i] = 0
        for j in range(queries[i]-x, queries[i]):
            if logs[i][0] == j:
                arr[i] += 1
    return arr

def minOperations(num1, num2):
    if num1 == 0:
        return 0

    i = 0
    while num1 > 0:
        if num1 % 2 == 0:
            num1 = num1 - 2**i + num2
        else:
            num1 = num1 - 2**i
        i += 1

    return i

def maxSum(nums1, nums2, queries):
    n = len(nums1)
    max_sum = -1
    for i in range(n):
        for j in range(n):
            if nums1[i] >= queries[i][0] and nums2[j] >= queries[i][1]:
                if nums1[i] + nums2[j] > max_sum:
                    max_sum = nums1[i] + nums2[j]
    return [max_sum]

def special_sum(nums):
    total = 0
    for i in range(len(nums)):
        if nums[i] % i == 0:
            total += nums[i]**2
    return total

def partition(nums):
    nums1 = []
    nums2 = []

    for num in nums:
        if num < nums1[-1]:
            nums1.append(num)
        else:
            nums2.append(num)

    return max(nums1) - min(nums2)

def maxPairs(words):
    max_pairs = 0
    for i in range(len(words)):
        for j in range(i+1, len(words)):
            if words[i] == words[j][::-1]:
                max_pairs += 1
    return max_pairs

def countSpecialPermutations(nums):
    # Initialize a dictionary to store the count of each permutation
    count = {}

    # Initialize the sum of the count of all permutations
    total_count = 0

    # Iterate over the array
    for num in nums:
        # Check if the current number is a special permutation
        if num in count:
            # Increment the count of the current permutation
            count[num] += 1
        else:
            # If the current number is not a special permutation, add it to the count
            count[num] = 1

        # Update the total count
        total_count += count[num]

    # Return the total count modulo 10^9 + 7
    return total_count % (10**9 + 7)

def concatenate_strings(x, y, z):
    if x == 0:
        return ""
    elif y == 0:
        return ""
    elif z == 0:
        return ""
    elif x == y:
        return x
    elif x == z:
        return y
    elif y == z:
        return x
    else:
        return concatenate_strings(x - 1, y, z - 1) + concatenate_strings(x, y - 1, z) + concatenate_strings(x, y, z - 1)

def maxJumps(nums, target):
    n = len(nums)
    dp = [[0] * (target + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(i):
            if nums[j] == target:
                dp[i][j] = dp[i - 1][j] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - nums[j] + 1])
    return dp[n][n]

def countCompleteSubarrays(nums):
    # Initialize a dictionary to store the count of each subarray
    count = {}

    # Initialize the count of complete subarrays to 0
    count['complete'] = 0

    # Iterate over the array
    for num in nums:
        # If the current number is not in the dictionary, add it to the dictionary
        if num not in count:
            count[num] = 1
        else:
            count[num] += 1

    # Return the count of complete subarrays
    return count['complete']

def maxDistance(mainTank, additionalTank):
    if mainTank < additionalTank:
        return 0

    fuel_remaining = mainTank - additionalTank
    distance_traveled = 0

    while fuel_remaining > 0:
        fuel_transferred = additionalTank - fuel_remaining
        distance_traveled += fuel_transferred
        fuel_remaining -= fuel_transferred

    return distance_traveled

def countSubarrays(nums):
    # Initialize a dictionary to store the number of ways to split the array into good subarrays
    count = {}

    # Initialize the count of good subarrays
    count[0] = 1

    # Iterate over the array
    for i in range(1, len(nums)):
        # Check if the current element is 1
        if nums[i] == 1:
            # If the current element is 1, increment the count of good subarrays
            count[i] += 1

    # Return the count of good subarrays modulo 10^9 + 7
    return count[len(nums)] % (10**9 + 7)

def countContinuousSubarrays(nums):
    # Initialize a counter to keep track of the number of continuous subarrays
    count = 0

    # Iterate through the array
    for i in range(len(nums)):
        # Check if the current subarray is continuous
        if (i + 1) <= len(nums) and (nums[i] - nums[i + 1]) <= 2:
            # Increment the counter
            count += 1

    return count

def maxLengthOfLongestNonDecreasingSubarray(nums1, nums2):
    nums3 = []
    for i in range(len(nums1)):
        if nums1[i] > nums2[i]:
            nums3.append(nums1[i])
        else:
            nums3.append(nums2[i])
    return max(len(nums3), key=len)

def maxLengthOfAlternatingSubarrays(nums):
    if not nums:
        return 0

    max_length = 0

    for i in range(len(nums)):
        if i % 2 == 0:
            s = nums[i]
            s_1 = s + 1
            s_2 = s - 1
            s_3 = s + 1
            s_4 = s - 1

            if s_1 > s_2 and s_2 > s_3 and s_3 > s_4:
                max_length = max(max_length, len(nums) - i + 1)
            else:
                max_length = max(max_length, len(nums) - i + 1)

    return max_length

def max_element(nums):
    nums.sort()
    max_val = nums[0]
    for i in range(1, len(nums)):
        if nums[i] > max_val:
            max_val = nums[i]
    return max_val

def find_prime_pairs(n):
    prime_pairs = []
    for i in range(2, n):
        if i > 1 and (i * i) % n == 0:
            prime_pairs.append([i, i])
    return sorted(prime_pairs, key=lambda x: x[0])

def atLeastTarget(hours, target):
    n = len(hours)
    total_hours = sum(hours)

    for i in range(n):
        if total_hours >= target:
            return i

    return -1

def split_string(words, separator):
    result = []
    for word in words:
        if word:
            result.append(word.split(separator))
    return result

def count_ways(n, x):
    # Initialize a set to store the unique integers
    unique_integers = set()

    # Initialize a dictionary to store the number of ways to express n as the sum of the x^th power of unique integers
    ways = {}

    # Iterate over all unique integers from 1 to n
    for i in range(1, n + 1):
        # Check if the current integer is in the set of unique integers
        if i in unique_integers:
            # If it is, increment the count of ways
            ways[i] = ways.get(i, 0) + 1
        else:
            # If it is not, add it to the set of unique integers
            unique_integers.add(i)

    # Return the number of ways n can be expressed as the sum of the x^th power of unique integers
    return ways.get(n, 0) % 10**9 + 7

def partition_beautiful_substrings(s):
    # Convert the string to binary
    binary_string = bin(int(s, 2))[2:]

    # Split the string into substrings
    substrings = []
    for i in range(len(binary_string)):
        if binary_string[i] == '1':
            substrings.append(binary_string[i:i+1])
        else:
            substrings.append(binary_string[i:i+1])

    # Find the minimum number of substrings
    min_substrings = min(len(substrings), len(s))

    return min_substrings

def longestValidSubstring(word, forbidden):
    # Initialize the length of the longest valid substring
    max_length = 0

    # Initialize a dictionary to store the length of each valid substring
    valid_substrings = {}

    # Iterate through the forbidden words
    for i in range(len(forbidden)):
        # Check if the current word is a substring of the forbidden word
        if word[i] in forbidden[i]:
            # If the current word is a substring of the forbidden word, update the length of the longest valid substring
            if word[i] in valid_substrings:
                max_length = max(max_length, valid_substrings[word[i]])
            else:
                valid_substrings[word[i]] = len(word[i])

    # Return the length of the longest valid substring
    return max_length

def reverse_string(s):
    # Initialize a new string to store the reversed string
    reversed_string = ""

    # Iterate over each character in the input string
    for char in s:
        # If the character is 'i', reverse the string
        if char == 'i':
            reversed_string = reversed_string[::-1]
        # Otherwise, append the character to the reversed string
        else:
            reversed_string += char

    # Return the final reversed string
    return reversed_string

def is_good_array(nums):
    base = [1, 2, ..., nums[-1] - 1, nums[-1]]
    return len(base) == nums[-1]

def maxScore(nums, x):
    total_score = 0
    for i in range(len(nums)):
        if i == 0:
            total_score += nums[i]
        else:
            if nums[i] % 2 != nums[i - 1] % 2:
                total_score += x
            else:
                total_score += nums[i]
    return total_score
print(maxScore([2,3,6,1,9,2], 5))  # Output: 13
print(maxScore([2,4,6,8], 3))  # Output: 20

def maxSumPair(nums):
    max_sum = 0
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if nums[i] == nums[j]:
                max_sum = max(max_sum, nums[i] + nums[j])
    return max_sum

def countInterestingSubarrays(nums, modulo, k):
    cnt = 0
    for i in range(len(nums)):
        if nums[i] % modulo == k:
            cnt += 1
    return cnt

def numPairs(nums, target):
    nums.sort()
    pairs = []
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if nums[i] + nums[j] < target:
                pairs.append((i, j))
    return pairs

def createGroups(usageLimits):
    groups = []
    for i in range(len(usageLimits)):
        if usageLimits[i] > 0:
            groups.append(usageLimits[i])
            usageLimits[i] -= 1
    return max(groups)

def find_pairs(coordinates, k):
    # Initialize a set to store the pairs
    pairs = set()

    # Iterate through the coordinates
    for i in range(len(coordinates)):
        for j in range(i+1, len(coordinates)):
            # Calculate the distance between the two points
            distance = coordinates[i][0] ^ coordinates[j][0] + coordinates[i][1] ^ coordinates[j][1]

            # Check if the distance is equal to k
            if distance == k:
                pairs.add((i, j))

    return len(pairs)

def is_acronym(words, s):
    for word in words:
        if word[0] in s:
            return True
    return False

def max_gold(n, offers):
    max_gold = 0
    for i in range(n):
        start_i, end_i, gold_i = offers[i]
        if start_i <= i <= end_i:
            max_gold = max(max_gold, gold_i)
    return max_gold

def count_symmetric_numbers(low, high):
    # Initialize a dictionary to store the count of symmetric numbers
    count = {}

    # Iterate over the range [low, high]
    for num in range(low, high + 1):
        # Check if the number is symmetric
        if num % 2 == 0:
            # If the number is symmetric, increment the count
            count[num] = count.get(num, 0) + 1
        else:
            # If the number is not symmetric, increment the count
            count[num] = count.get(num, 0)

    # Return the count of symmetric numbers
    return count[high] - count[low]

def swap_chars(s1, s2):
    i, j = 0, 0
    while i < len(s1) and j < len(s2):
        if s1[i] == s2[j]:
            s1[i], s2[j] = s2[j], s1[i]
            i += 1
            j += 1
        else:
            i += 1
    return s1 == s2

def min_absolute_diff(nums, x):
    min_diff = float('inf')
    min_i = 0
    min_j = 0
    for i in range(len(nums)):
        if abs(i - min_i) >= x:
            if abs(nums[i] - nums[min_j]) < min_diff:
                min_diff = abs(nums[i] - nums[min_j])
                min_i = i
                min_j = min_j + 1
    return min_diff

def count_beautiful_numbers(low, high, k):
    # Initialize a counter to keep track of the number of beautiful numbers
    beautiful_numbers = 0

    # Iterate through the range [low, high]
    for i in range(low, high + 1):
        # Check if the number is divisible by k
        if i % k == 0:
            # If the number is divisible by k, it is a beautiful number
            beautiful_numbers += 1

    return beautiful_numbers

def isSubsequence(str1, str2):
    # Check if str1 and str2 are equal
    if str1 == str2:
        return True

    # Check if str1 is a subsequence of str2
    if str1[0] == str2[0]:
        return True

    # Check if str1 is a subsequence of str2
    for i in range(1, len(str1)):
        if str1[i] != str2[i]:
            return False

    return True

def product_matrix(grid):
    n, m = len(grid), len(grid[0])
    p = [[0] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            p[i][j] = grid[i][j] * (grid[i][j] % 12345) % 12345
    return p

def right_shift(nums):
    n = len(nums)
    if n == 0:
        return -1

    for i in range(n):
        nums[i] = nums[i] - 1

    for i in range(n-1, -1, -1):
        nums[i] = nums[i] + 1

    return n

def maxElementSum(nums):
    max_sum = 0
    for i in range(len(nums)):
        if i == 0:
            max_sum = nums[i]
        else:
            max_sum = max(max_sum, nums[i] + nums[i-1])
    return max_sum

def maxOddBinary(s):
    # Convert the string to binary
    binary = bin(int(s, 2))[2:]

    # Find the maximum odd number from the binary string
    max_odd = 0
    for i in range(len(binary)):
        if binary[i] == '1':
            max_odd = max(max_odd, int(binary[i:i+2], 2))

    # Return the maximum odd binary number
    return binary[::-1][:max_odd]

def maxSubarrays(nums):
    def helper(nums, l, r):
        if l > r:
            return 0
        if nums[l] == 0:
            return 1
        if nums[l] == nums[r]:
            return 1
        if nums[l] + nums[r] == 0:
            return 1
        if nums[l] + nums[r] == nums[l]:
            return 1
        if nums[l] + nums[r] == nums[r]:
            return 1
        return helper(nums, l + 1, r - 1) + helper(nums, l, r - 1)
    return helper(nums, 0, len(nums) - 1)

def sumSetBits(nums, k):
    # Convert the binary representation of the indices to a list of bits
    bits = [0] * (len(nums) + 1)
    for i in range(len(nums)):
        bits[i] = nums[i] & (1 << (i % 8))

    # Initialize the sum
    sum = 0

    # Iterate over the list of bits
    for i in range(len(bits)):
        # If the bit is set, add 1 to the sum
        if bits[i] != 0:
            sum += 1

    return sum

def distinct_count_of_subarrays(nums):
    # Initialize a dictionary to store the distinct counts
    distinct_counts = {}

    # Iterate over the array
    for i in range(len(nums)):
        # Check if the current subarray is already in the dictionary
        if i in distinct_counts:
            # If it is, increment the count
            distinct_counts[i] += 1
        else:
            # If it is not, add it to the dictionary
            distinct_counts[i] = 1

    # Sum the distinct counts of all subarrays
    return sum(distinct_counts.values())

def lastVisited(words):
    nums = [int(word) for word in words]
    nums_reverse = list(reversed(nums))
    k = 0
    while k < len(nums_reverse):
        if nums_reverse[k] == -1:
            return [nums_reverse[k]]
        k += 1
    return [-1] * len(nums)

def group_indices(nums):
    n = len(nums)
    groups = [[] for _ in range(n)]

    for i in range(n):
        for j in range(i+1, n):
            if nums[i] == nums[j]:
                groups[i].append(j)
                groups[j].append(i)

    for i in range(n):
        if len(groups[i]) == 1:
            return i

    return -1

