def is_palindrome(s):
    s = ''.join(c for c in s if c.isalnum())
    return s == s[::-1]

def is_palindrome_by_queries(s, queries):
    answer = []
    for i in range(len(s)):
        if is_palindrome(s[i:i+len(queries[i])]):
            answer.append(True)
        else:
            answer.append(False)
    return answer

