def equal_strings(s1, s2, s3):
    # Check if the strings are equal
    if s1 == s2 and s1 == s3:
        return 0

    # Check if the strings are not equal
    if s1 != s2 and s1 != s3 and s2 != s3:
        return -1

    # Check if the strings are equal
    if len(s1) >= 2 and len(s2) >= 2 and len(s3) >= 2:
        return min(equal_strings(s1, s2, s3), equal_strings(s2, s1, s3), equal_strings(s3, s2, s1))

    return -1

