def countGoodPartitions(nums):
    # Initialize a dictionary to store the number of good partitions
    count = {}

    # Initialize the sum of good partitions
    total_good_partitions = 0

    # Iterate over the array
    for i in range(len(nums)):
        # Check if the current element is in the list
        if nums[i] in nums:
            # If the current element is in the list, increment the count
            count[nums[i]] = count.get(nums[i], 0) + 1
        else:
            # If the current element is not in the list, increment the count
            count[nums[i]] = 1

    # Initialize the sum of good partitions
    total_good_partitions = 0

    # Iterate over the dictionary
    for key, value in count.items():
        # If the number of good partitions is greater than 0, add 1 to the total
        total_good_partitions += value

    # Return the total number of good partitions
    return total_good_partitions % (10**9 + 7)

def findSubarrays(nums, k):
    # Initialize a dictionary to store the count of each element
    count = {}

    # Initialize a counter to keep track of the number of times each element appears
    count[nums[0]] = 1

    # Iterate over the array
    for num in nums:
        # If the current element is not in the dictionary, add it to the dictionary
        if num not in count:
            count[num] = 1
        # If the current element is in the dictionary, increment the count
        else:
            count[num] += 1

    # Return the number of subarrays where the maximum element appears at least k times
    return sum(count.values())

