    count = {}

    # Iterate over the word
    for i in range(len(word)):
        # Initialize a counter for each complete substring
        count[word[i]] = 0

        # Iterate over the characters in the word
        for j in range(i + 1, len(word)):
            # If the difference between the two characters is at most 2
            if abs(word[i] - word[j]) <= 2:
                # Increment the count of the complete substring
                count[word[i]] += 1

    # Return the count of complete substrings
    return count[word[0]]

