            elif pattern[j] == -1:
                if nums[i] < nums[j]:
                    count += 1
    return count

def maxConsecutive(nums):
    max_consecutive = 0
    for i in range(len(nums)):
        if i == 0 or nums[i] > nums[i-1]:
            max_consecutive = max(max_consecutive, i-1)
        elif i == len(nums)-1 or nums[i] > nums[i+1]:
            max_consecutive = max(max_consecutive, i+1)
    return max_consecutive

