def longestCommonPrefix(arr1, arr2):
    # Initialize a dictionary to store the longest common prefix
    longest_common_prefix = {}

    # Iterate over all pairs (x, y)
    for x in arr1:
        for y in arr2:
            # Check if x and y are in the dictionary
            if x in longest_common_prefix and y in longest_common_prefix[x]:
                # If they are, update the length of the longest common prefix
                longest_common_prefix[x][y] = max(longest_common_prefix[x][y], longest_common_prefix[x][y] + 1)
            else:
                # If they are not, add them to the dictionary
                longest_common_prefix[x][y] = 1

    # Return the length of the longest common prefix
    return max(longest_common_prefix.values())

def distribute(nums):
    arr1 = [nums[0]]
    arr2 = [nums[1]]
    for i in range(2, len(nums)):
        if nums[i] > nums[i-1]:
            arr1.append(nums[i])
        else:
            arr2.append(nums[i])
    result = arr1 + arr2
    return result

def is_cheating_allowed(S, T):
    # Check if S and T are valid strings
    if not all(c.isalpha() or c == '@' for c in S) or not all(c.isalpha() or c == '@' for c in T):
        return False

    # Check if the two rows are the same
    if len(S) != len(T):
        return False

    # Check if the two rows can be rearranged freely
    for i in range(len(S)):
        for j in range(i + 1, len(S)):
            if S[i] == S[j]:
                S[i], S[j] = S[j], S[i]
                break
    for i in range(len(T)):
        for j in range(i + 1, len(T)):
            if T[i] == T[j]:
                T[i], T[j] = T[j], T[i]
                break
    return True

def find_greatest_value(N, S):
    T = set()
    for i in range(len(S)):
        if S[i] == '?':
            T.add(0)
            T.add(1)
        else:
            T.add(int(S[i]))

    for i in range(len(T)):
        if T[i] <= N:
            return T[i]
    return -1

def can_reach_goal(grid, start, goal, T):
    # Initialize variables
    visited = [False] * (len(grid) + 1)
    visited[start] = True
    candies = [0] * (len(grid) + 1)
    candies[start] = 1

    # Traverse the grid
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '.':
                continue
            if grid[i][j] == 'S':
                candies[i] += 1
                if visited[i] and candies[i] >= goal:
                    return candies[i]
            elif grid[i][j] == 'G':
                candies[i] -= 1
                if visited[i] and candies[i] <= goal:
                    return candies[i]
            elif grid[i][j] == '#':
                visited[i] = True
                candies[i] = 1
            elif grid[i][j] == 'o':
                candies[i] = 1
                visited[i] = True

    return -1

