def rearrange_strings(S_1, S_2, ..., S_N):
    # Initialize a dictionary to keep track of the characters in each string
    char_dict = {char: i for i, char in enumerate(S_1)}

    # Initialize a list to store the rearranged strings
    rearranged_strings = []

    # Iterate over the input strings
    for i in range(len(S_1)):
        # If the current string is not a valid permutation, skip it
        if i > 0 and S_1[i] != S_1[i - 1]:
            continue

        # If the current string is a valid permutation, add it to the list
        if i == 0:
            rearranged_strings.append(S_1[i])
        else:
            rearranged_strings.append(S_1[i] + S_1[i - 1])

    # Check if the list of rearranged strings is valid
    if not all(char_dict[char] == i for i, char in enumerate(rearranged_strings)):
        return False

    # Return True if all strings are valid permutations
    return True

def is_similar_strings(S, T):
    # Check if S and T are similar strings
    if len(S) != len(T):
        return False

    # Check if all characters in S and T are similar characters
    for i in range(len(S)):
        if S[i] != T[i]:
            return False

    return True
