def time_to_make_string_equal(S, X, Y, Z):
    # Initialize variables
    total_time = 0

    # Calculate the time to press the Caps Lock key
    if S == "":
        total_time += Z
    else:
        total_time += X + Y

    # Calculate the time to press the 'a' key
    if S == "A":
        total_time += X
    else:
        total_time += Y

    # Calculate the time to press the Shift key and 'a' key simultaneously
    if S == "aA":
        total_time += X + Y
    else:
        total_time += X

    # Calculate the time to press the 'a' key
    if S == "AaA":
        total_time += X
    else:
        total_time += Y

    # Calculate the time to press the Caps Lock key
    if S == "aaAAAAaAaaAAAAaAaaAaAAaaaAAAAA":
        total_time += Z
    else:
        total_time += X

    return total_time
