def approximate_number(N):
    if N <= 10**3 - 1:
        return N
    elif 10**3 <= N <= 10**4 - 1:
        return str(int(N) // 10) + '0'
    elif 10**4 <= N <= 10**5 - 1:
        return str(int(N) // 100) + '0'
    elif 10**5 <= N <= 10**6 - 1:
        return str(int(N) // 1000) + '0'
    elif 10**6 <= N <= 10**7 - 1:
        return str(int(N) // 10000) + '0'
