def find_nearest_water_station(start_point, goal_point, water_stations):
    # Calculate the distance between the start and goal points
    distance = abs(start_point[0] - goal_point[0]) + abs(start_point[1] - goal_point[1])

    # Calculate the distance between the start and each water station
    for i in range(len(water_stations)):
        distance += abs(water_stations[i][0] - start_point[0]) + abs(water_stations[i][1] - start_point[1])

    # Find the nearest water station
    nearest_water_station = water_stations[0]
    for i in range(1, len(water_stations)):
        if distance < nearest_water_station[0] + water_stations[i][0]:
            nearest_water_station = water_stations[i]

    # Return the nearest water station
    return nearest_water_station[0]

