def find_cycle(graph):
    # Initialize a set to store the vertices of the cycle
    cycle = set()

    # Iterate through the graph
    for i in range(len(graph) - 1):
        # If the current vertex is not the last vertex, add it to the cycle
        if i != len(graph) - 1:
            cycle.add(graph[i])

            # If the current vertex is the last vertex, add the previous vertex to the cycle
            if i == 0:
                cycle.add(graph[i - 1])

    # If the cycle is not empty, return it
    return cycle

