    if N == 0:
        return 0
    if M == 0:
        return 1
    if S[0] == T[0]:
        return 1
    if S[-1] == T[-1]:
        return 2
    if S[0] == T[M-1]:
        return 2
    if S[N-1] == T[0]:
        return 2
    if S[N-1] == T[M-1]:
        return 2
    return 3

