    balls_in_box4 = 1
    balls_in_box5 = 1
    balls_in_box6 = 1

    # Initialize the number of different colors of balls in box b
    different_colors_in_box_b = 0

    # Move all balls from box a to box b
    for i in range(N):
        if C[i] == 1:
            balls_in_box1 += 1
        elif C[i] == 2:
            balls_in_box2 += 1
        elif C[i] == 3:
            balls_in_box3 += 1
        elif C[i] == 4:
            balls_in_box4 += 1
        elif C[i] == 5:
            balls_in_box5 += 1
        elif C[i] == 6:
            balls_in_box6 += 1

    # Move all balls from box b to box a
    for i in range(N):
        if C[i] == 1:
            balls_in_box1 -= 1
        elif C[i] == 2:
            balls_in_box2 -= 1
        elif C[i] == 3:
            balls_in_box3 -= 1
        elif C[i] == 4:
