def lexicographical_order(N):
    # Initialize a list to store triples
    triples = []

    # Generate all triples of non-negative integers
    for x in range(1, N + 1):
        for y in range(1, N + 1):
            for z in range(1, N + 1):
                if x + y + z <= N:
                    triples.append((x, y, z))

    # Sort the triples in ascending lexicographical order
    triples.sort(key=lambda x: (x[0], x[1], x[2]))

    # Print all triples
    for triple in triples:
        print(triple)

