def max_size_pyramid_sequence(A):
    # Initialize the size of the pyramid sequence
    size = 1

    # Iterate over the sequence A
    for i in range(len(A)):
        # Choose one term of the sequence and decrease its value by 1
        if i == 0:
            size += 1
        elif i == len(A) - 1:
            size -= 1
        else:
            size += 1

        # Remove the first or last term
        if i == 0:
            size -= 1
        elif i == len(A) - 1:
            size -= 1
        else:
            size -= 1

        # Check if the size of the pyramid sequence is greater than the current size
        if size > size:
            size = size + 1

    return size
