    return count

def maxSubstringLength(s):
    # Initialize a dictionary to store the count of each character
    count = {}

    # Initialize the length of the substring
    length = 0

    # Iterate through the string
    for i in range(len(s)):
        # If the character is not in the dictionary, add it to the dictionary
        if s[i] not in count:
            count[s[i]] = 1
        # If the character is in the dictionary, update the length
        else:
            count[s[i]] += 1

        # If the length of the substring is greater than the current length, update the length
        if length + 1 > count[s[i]]:
            length = count[s[i]]

    # Return the length of the substring
    return length

def mostFrequentID(nums, freq):
    n = len(nums)
    ans = [0] * n

    for i in range(n):
        if freq[i] > 0:
            ans[i] = max(ans[i], nums[i] + freq[i])
        else:
            ans[i] = max(ans[i], nums[i] - freq[i])

    return ans

