def remove_point(points):
    # Initialize the maximum distance to 0
    max_distance = 0

    # Iterate through the points
    for i in range(len(points)):
        # Calculate the Manhattan distance between the current point and the previous point
        distance = abs(points[i][0] - points[i-1][0]) + abs(points[i][1] - points[i-1][1])

        # Update the maximum distance if the current point is removed
        if i == 0:
            max_distance = max(max_distance, distance)
        else:
            max_distance = max(max_distance, distance)

    return max_distance

def distance(s, k):
    # Convert s to lowercase
    s = ''.join(c.lower() for c in s)

    # Initialize a dictionary to store the minimum distance
    min_distance = float('inf')
    min_index = 0

    # Iterate over the characters in s
    for i in range(len(s)):
        # If the character is not in the dictionary, add it to the dictionary
        if s[i] not in min_distance:
            min_distance[s[i]] = i
            min_index = i

    # If the dictionary is empty, return the original string
    if min_index == len(s):
        return s

    # Find the minimum distance between the original string and the string after the changes
    for i in range(len(s)):
        if s[i] != s[min_index]:
            distance = min_distance[s[i]] - min_distance[s[min_index]]
            if distance <= k:
                return s[:min_index] + s[min_index+1:min_index+distance]

    # If the distance is greater than k, return the original string
    return s

def maxDistanceBetweenPrimeNumbers(nums):
    prime_nums = [num for num in nums if all(num % i != 0 for i in range(2, int(num ** 0.5) + 1))]
    return max(abs(num - prime_nums[0]) for num in prime_nums)

def encrypt(nums):
    encrypted_nums = []
    for num in nums:
        encrypted_nums.append(max(num, key=num))
    return sum(encrypted_nums)

def powerOfSubsequences(nums, k):
    if k == 0:
        return 0

    power = 0
    for i in range(len(nums)):
        power += nums[i] * powerOfSubsequences(nums, k - 1)

    return power

