def increase_or_decrease(nums1, nums2, x):
    # Check if nums1 and nums2 are equal
    if nums1 == nums2:
        return x

    # If nums1 is greater than nums2, increase nums1
    if nums1 > nums2:
        return nums1 + x

    # If nums1 is less than nums2, decrease nums1
    elif nums1 < nums2:
        return nums2 - x

    # If nums1 is equal to nums2, return 0
    else:
        return 0

def min_nums(n, x):
    nums = [x]
    for i in range(n - 1):
        nums.append(nums[-1] & nums[i + 1])
    return min(nums)

def median(nums):
    # Sort the array
    nums.sort()

    # Get the median
    n = len(nums)
    if n % 2 == 0:
        return (nums[n // 2] + nums[n // 2 - 1]) / 2
    else:
        return nums[n // 2]

def is_valid_word(word):
    # Check if the word is valid
    if len(word) < 3 or not all(char.isalpha() for char in word):
        return False

    # Check if the word contains at least one vowel
    vowels = set('aeiouAEIOU')
    if not any(char in vowels for char in word):
        return False

    # Check if the word contains at least one consonant
    consonants = set('bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ')
    if not any(char in consonants for char in word):
        return False

    return True

def minLengthAnagram(s):
    # Convert the string to lowercase
    s = s.lower()

    # Create a dictionary to store the frequency of each letter
    freq = {}
    for char in s:
        freq[char] = freq.get(char, 0) + 1

    # Find the minimum length of the string t
    min_length = float('inf')
    for t in freq:
        if len(t) < min_length:
            min_length = len(t)

    return min_length

